-- Disposable local records; all writes roll back.
begin;set local search_path=pg_catalog,public,extensions;
create extension if not exists pgtap with schema extensions;select extensions.no_plan();
alter table auth.users disable trigger on_auth_user_created;
insert into auth.users(id,email) values('d1100000-0000-4000-8000-000000000001','procurement-owner@local.invalid'),('d1100000-0000-4000-8000-000000000002','procurement-employee@local.invalid');
alter table auth.users enable trigger on_auth_user_created;
insert into public.companies(id,name,operating_timezone) values('d1200000-0000-4000-8000-000000000001','Synthetic procurement contractor','UTC'),('d1200000-0000-4000-8000-000000000002','Other synthetic contractor','UTC');
insert into public.profiles(id,company_id,role,full_name) values('d1100000-0000-4000-8000-000000000001','d1200000-0000-4000-8000-000000000001','owner','Synthetic owner'),('d1100000-0000-4000-8000-000000000002','d1200000-0000-4000-8000-000000000001','employee','Synthetic employee');
insert into public.projects(id,company_id,job_number,name,status) values('d1300000-0000-4000-8000-000000000001','d1200000-0000-4000-8000-000000000001','SYN-PO','Synthetic purchasing job','active'),('d1300000-0000-4000-8000-000000000002','d1200000-0000-4000-8000-000000000002','SYN-FOREIGN','Foreign purchasing job','active');
insert into public.vendors(id,company_id,name) values('d1400000-0000-4000-8000-000000000001','d1200000-0000-4000-8000-000000000001','Synthetic supplier');
insert into public.cost_codes(id,company_id,code,name,cost_type) values('d1500000-0000-4000-8000-000000000001','d1200000-0000-4000-8000-000000000001','51410','Synthetic concrete','material');
insert into public.pour_plans(id,company_id,project_id,name,status) values('d1600000-0000-4000-8000-000000000001','d1200000-0000-4000-8000-000000000001','d1300000-0000-4000-8000-000000000001','Explicit held pour','hold'),('d1600000-0000-4000-8000-000000000002','d1200000-0000-4000-8000-000000000001','d1300000-0000-4000-8000-000000000001','Previously authorized pour','authorized');
insert into public.production_tasks(id,company_id,name,production_unit) values('d1700000-0000-4000-8000-000000000001','d1200000-0000-4000-8000-000000000001','Synthetic concrete placement','CY');
insert into public.work_packages(id,company_id,project_id,name) values('d1800000-0000-4000-8000-000000000001','d1200000-0000-4000-8000-000000000001','d1300000-0000-4000-8000-000000000001','Synthetic pour package');
insert into public.work_package_operations(id,company_id,work_package_id,production_task_id,planned_quantity,unit,measurement_method,pour_plan_id,requires_prior_operations) values('d1850000-0000-4000-8000-000000000001','d1200000-0000-4000-8000-000000000001','d1800000-0000-4000-8000-000000000001','d1700000-0000-4000-8000-000000000001',10,'CY','ticket','d1600000-0000-4000-8000-000000000001',false);
insert into public.company_documents(id,company_id,project_id,title,document_type,storage_path) values('d1860000-0000-4000-8000-000000000001','d1200000-0000-4000-8000-000000000001','d1300000-0000-4000-8000-000000000001','Synthetic evidence only','concrete_ticket','synthetic/local-only-ticket.pdf');
create temp table procurement_input as select jsonb_build_object('project_id','d1300000-0000-4000-8000-000000000001','vendor_id','d1400000-0000-4000-8000-000000000001','quote_date','2026-10-16','pour_plan_id','d1600000-0000-4000-8000-000000000001') header,
 jsonb_build_object('cost_code_id','d1500000-0000-4000-8000-000000000001','description','Synthetic concrete','quantity',10,'unit','CY','unit_cost',10,'sales_tax',0) line;
create temp table procurement_results(key text primary key,value jsonb);grant all on procurement_results to authenticated;grant select on procurement_input to authenticated;
create function pg_temp.procure(n integer,c text,p jsonb) returns jsonb language sql as $$select public.carez_procurement_command_v1(('d1900000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,c,p)$$;
select set_config('request.jwt.claim.sub','d1100000-0000-4000-8000-000000000001',true);set local role authenticated;
select pg_temp.procure(1,'create_quote',(select header from procurement_input)) as quote_result \gset
insert into procurement_results values('quote',:'quote_result'::jsonb);
select pg_temp.procure(2,'add_quote_line',(select line||jsonb_build_object('vendor_quote_id',(select value->>'id' from procurement_results where key='quote')) from procurement_input));
insert into procurement_results values('po',pg_temp.procure(3,'convert_quote',(select jsonb_build_object('vendor_quote_id',value->>'id') from procurement_results where key='quote')));
select pg_temp.procure(4,'issue_po',(select jsonb_build_object('purchase_order_id',value->>'id','issue_date','2026-10-16') from procurement_results where key='po'));
create function pg_temp.resource(n integer,c text,p jsonb) returns jsonb language sql as $$select public.carez_resource_command_v1(('d1950000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,c,p)$$;
select extensions.lives_ok($$insert into procurement_results values('inventory',pg_temp.resource(1,'create_inventory','{"name":"Synthetic material","unit":"CY","quantity_on_hand":10,"reorder_point":0,"average_unit_cost":2}'))$$,'create a recorded inventory opening');
select extensions.lives_ok($$select pg_temp.resource(1,'create_inventory','{"name":"Synthetic material","unit":"CY","quantity_on_hand":10,"reorder_point":0,"average_unit_cost":2}')$$,'inventory create retry is idempotent');
select extensions.is((select count(*)::int from public.inventory_items),1,'one inventory record after retry');
select extensions.lives_ok($$insert into procurement_results values('unknown-cost',pg_temp.resource(2,'create_inventory','{"name":"Synthetic cost not recorded","unit":"EA","quantity_on_hand":0,"reorder_point":0}'))$$,'inventory can retain unknown unit cost without manufacturing zero');
select extensions.ok((select average_unit_cost is null from public.inventory_items where name='Synthetic cost not recorded'),'unknown cost remains null');
select extensions.throws_like($$select pg_temp.resource(3,'create_inventory','{"name":"Bad stock","unit":"EA","quantity_on_hand":"NaN","reorder_point":0}')$$,'%finite nonnegative%','invalid inventory opening rejected');
select extensions.lives_ok($$insert into procurement_results values('resource',pg_temp.resource(3,'create',(select jsonb_build_object('work_package_operation_id','d1850000-0000-4000-8000-000000000001','resource_type','material','label','Synthetic planned material','required_quantity',4,'unit','CY','inventory_item_id',(select value->>'id' from procurement_results where key='inventory'),'reserve_quantity',4,'purchase_order_line_id',id,'required_before_start',true) from public.purchase_order_lines)))$$,'requirement, issued PO linkage and stock reservation commit together');
select extensions.is((select count(*)::int from public.inventory_reservations),1,'one planned material reservation');
select extensions.is((select work_package_operation_id from public.purchase_order_lines),'d1850000-0000-4000-8000-000000000001'::uuid,'issued line receives its governed operation link');
select extensions.is((select total_cost from public.purchase_order_lines),100::numeric,'issued financial values remain frozen');
select extensions.throws_like($$select pg_temp.resource(90,'create',(select jsonb_build_object('work_package_operation_id','d1850000-0000-4000-8000-000000000001','resource_type','material','label','Second demand cannot reuse the receipt','required_quantity',4,'unit','CY','purchase_order_line_id',id,'required_before_start',true) from public.purchase_order_lines))$$,'%PO line already supplies another requirement%','one receipt source cannot be credited in full to two requirements');
select extensions.is((select count(*)::int from public.work_package_resource_requirements),1,'rejected shared source leaves no partial requirement');
select extensions.throws_like($$update public.purchase_order_lines set total_cost=1$$,'%permission denied%','raw issued financial edit remains denied');
reset role;set local role postgres;
update public.inventory_items set average_unit_cost='NaN'::numeric where name='Synthetic material';
reset role;set local role authenticated;
select extensions.throws_like($$select pg_temp.resource(4,'consume',(select jsonb_build_object('requirement_id',value->>'id') from procurement_results where key='resource'))$$,'%Recorded inventory cost is invalid%','invalid legacy inventory cost cannot enter a governed movement');
select extensions.is((select count(*)::int from public.inventory_transactions),0,'failed cost validation leaves no movement');
reset role;set local role postgres;update public.inventory_items set average_unit_cost=2 where name='Synthetic material';reset role;set local role authenticated;
reset role;set local role postgres;
update public.work_package_resource_requirements set inventory_item_id=(select (value->>'id')::uuid from procurement_results where key='unknown-cost') where id=(select (value->>'id')::uuid from procurement_results where key='resource');
reset role;set local role authenticated;
select extensions.throws_like($$select pg_temp.resource(4,'consume',(select jsonb_build_object('requirement_id',value->>'id') from procurement_results where key='resource'))$$,'%Reservation inventory does not match%','legacy mismatched reservation cannot consume a different inventory item');
select extensions.is((select count(*)::int from public.inventory_transactions),0,'mismatched reservation leaves no stock movement');
reset role;set local role postgres;
update public.work_package_resource_requirements set inventory_item_id=(select (value->>'id')::uuid from procurement_results where key='inventory') where id=(select (value->>'id')::uuid from procurement_results where key='resource');
reset role;set local role authenticated;
select extensions.lives_ok($$select pg_temp.resource(4,'consume',(select jsonb_build_object('requirement_id',value->>'id') from procurement_results where key='resource'))$$,'reserved material consumption is governed');
select extensions.is((select quantity_on_hand from public.inventory_items where name='Synthetic material'),6::numeric,'consumption decrements stock once');
select extensions.lives_ok($$select pg_temp.resource(4,'consume',(select jsonb_build_object('requirement_id',value->>'id') from procurement_results where key='resource'))$$,'consumption request replay returns confirmed result');
select extensions.lives_ok($$select pg_temp.resource(5,'consume',(select jsonb_build_object('requirement_id',value->>'id') from procurement_results where key='resource'))$$,'already-consumed source cannot be consumed twice with a new request');
select extensions.is((select count(*)::int from public.inventory_transactions),1,'one physical consumption movement');
select extensions.throws_like($$select pg_temp.resource(6,'reserve_material',(select jsonb_build_object('requirement_id',(select value->>'id' from procurement_results where key='resource'),'inventory_item_id',value->>'id','quantity',3) from procurement_results where key='inventory'))$$,'%Consumed inventory reservation is immutable%','consumed reservation cannot be rewritten');
select extensions.throws_like($$select pg_temp.resource(6,'delete',(select jsonb_build_object('requirement_id',value->>'id') from procurement_results where key='resource'))$$,'%Consumed material requirement cannot be deleted%','consumed source history is retained');
select extensions.lives_ok($$select pg_temp.resource(6,'adjust_inventory',(select jsonb_build_object('inventory_item_id',value->>'id','quantity',2,'transaction_type','in','transaction_date','2026-10-16') from procurement_results where key='inventory'))$$,'manual stock adjustment and ledger movement commit atomically');
select extensions.lives_ok($$select pg_temp.resource(6,'adjust_inventory',(select jsonb_build_object('inventory_item_id',value->>'id','quantity',2,'transaction_type','in','transaction_date','2026-10-16') from procurement_results where key='inventory'))$$,'stock adjustment retry does not add stock twice');
select extensions.is((select quantity_on_hand from public.inventory_items where name='Synthetic material'),8::numeric,'confirmed stock includes one adjustment');
select extensions.throws_like($$select pg_temp.resource(7,'adjust_inventory',(select jsonb_build_object('inventory_item_id',value->>'id','quantity',9,'transaction_type','out','transaction_date','2026-10-16') from procurement_results where key='inventory'))$$,'%cannot go below zero%','insufficient stock rollback includes the movement');
select extensions.is((select count(*)::int from public.inventory_transactions),2,'failed adjustment creates no orphan movement');
select extensions.throws_like($$update public.inventory_items set quantity_on_hand=99$$,'%permission denied%','raw stock overwrite denied');
select extensions.throws_like($$delete from public.inventory_transactions$$,'%permission denied%','raw stock history deletion denied');
select extensions.throws_like($$delete from public.inventory_reservations$$,'%permission denied%','raw reservation deletion denied');
select extensions.throws_like($$select public.consume_work_package_inventory((select (value->>'id')::uuid from procurement_results where key='resource'))$$,'%permission denied%','legacy consumption RPC cannot bypass request boundary');
select extensions.lives_ok($$select pg_temp.resource(7,'waive',(select jsonb_build_object('requirement_id',value->>'id','waiver_reason','Synthetic owner decision') from procurement_results where key='resource'))$$,'explicit resource waiver retains its reason');
select extensions.lives_ok($$select pg_temp.resource(8,'restore',(select jsonb_build_object('requirement_id',value->>'id') from procurement_results where key='resource'))$$,'restoration uses governed source path');
select extensions.ok((select waived_at is null from public.work_package_resource_requirements where id=(select (value->>'id')::uuid from procurement_results where key='resource')),'restored gate is not waived');
reset role;set local role postgres;
insert into public.equipment_assets(id,company_id,name,status,active) values('d1960000-0000-4000-8000-000000000001','d1200000-0000-4000-8000-000000000001','Synthetic equipment','available',true),('d1960000-0000-4000-8000-000000000002','d1200000-0000-4000-8000-000000000002','Foreign equipment','available',true);
reset role;set local role authenticated;
select extensions.lives_ok($$insert into procurement_results values('equipment-resource',pg_temp.resource(9,'create','{"work_package_operation_id":"d1850000-0000-4000-8000-000000000001","resource_type":"equipment","label":"Synthetic booked equipment","required_quantity":1,"unit":"EA","equipment_asset_id":"d1960000-0000-4000-8000-000000000001","reservation_start":"2026-10-16","reservation_end":"2026-10-17","equipment_confirmed":true,"required_before_start":true}'))$$,'equipment requirement and confirmed booking commit together');
select extensions.is((select count(*)::int from public.equipment_reservations),1,'one equipment booking');
select extensions.throws_like($$select pg_temp.resource(10,'reserve_equipment',(select jsonb_build_object('requirement_id',value->>'id','equipment_asset_id','d1960000-0000-4000-8000-000000000002','start_date','2026-10-18','end_date','2026-10-19','confirmed',true) from procurement_results where key='equipment-resource'))$$,'%Active equipment unavailable%','foreign equipment cannot replace a known booking');
select extensions.is((select equipment_asset_id from public.equipment_reservations),'d1960000-0000-4000-8000-000000000001'::uuid,'failed equipment selection preserves original booking');
select extensions.throws_like($$select pg_temp.resource(10,'reserve_equipment',(select jsonb_build_object('requirement_id',value->>'id','equipment_asset_id','d1960000-0000-4000-8000-000000000001','start_date','2026-10-19','end_date','2026-10-18','confirmed',true) from procurement_results where key='equipment-resource'))$$,'%end cannot precede start%','invalid reservation interval cannot partially change source');
select extensions.lives_ok($$select pg_temp.resource(10,'reserve_equipment',(select jsonb_build_object('requirement_id',value->>'id','equipment_asset_id','d1960000-0000-4000-8000-000000000001','start_date','2026-10-18','end_date','2026-10-19','confirmed',true) from procurement_results where key='equipment-resource'))$$,'existing equipment booking can move atomically');
select extensions.is((select start_date from public.equipment_reservations),'2026-10-18'::date,'recorded booking carries confirmed dates');
select extensions.is((select result->'equipment_reservation_before'->>'start_date' from public.financial_command_requests where request_id='d1950000-0000-4000-8000-000000000010'),'2026-10-16','equipment move retains the previous booking facts');
select extensions.ok((select result->'reservation_before' is not null from public.financial_command_requests where request_id='d1950000-0000-4000-8000-000000000004'),'consumption request retains prior reservation facts');
select set_config('request.jwt.claim.sub','d1100000-0000-4000-8000-000000000002',true);
select extensions.throws_like($$select pg_temp.resource(9,'create_inventory','{"name":"Denied","unit":"EA","quantity_on_hand":0,"reorder_point":0}')$$,'%Owner or office authority%','employee cannot mutate resource/stock authority');
select * from extensions.finish();rollback;
